import React, { useState, useMemo } from 'react';
import { 
  Search, 
  CheckCheck, 
  Clock, 
  User, 
  MessageSquare, 
  Filter,
  MoreVertical,
  Pin,
  Archive,
  Trash2,
  Mail,
  Phone,
  Star,
  Crown,
  Shield,
  Sparkles
} from 'lucide-react';

const MessagesList = ({ 
  conversations = [], 
  currentConversation, 
  loading, 
  onSelectConversation,
  isAdmin = false,
  user 
}) => {
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('all');
  const [hoveredConversation, setHoveredConversation] = useState(null);
  const [showMenu, setShowMenu] = useState(null);

  const userData = user || {};

  const filteredConversations = useMemo(() => {
    let filtered = conversations || [];

    if (search.trim()) {
      filtered = filtered.filter(conv => {
        if (!conv) return false;

        let otherUserName = '';
        if (isAdmin) {
          otherUserName = `${conv.user_first_name || ''} ${conv.user_last_name || ''}`.toLowerCase();
        } else {
          otherUserName = `${conv.admin_first_name || ''} ${conv.admin_last_name || ''}`.toLowerCase();
        }

        const searchLower = search.toLowerCase();
        return otherUserName.includes(searchLower) ||
               (conv.email && conv.email.toLowerCase().includes(searchLower)) ||
               (conv.last_message && conv.last_message.toLowerCase().includes(searchLower));
      });
    }

    if (filter === 'unread') {
      filtered = filtered.filter(conv => (conv.unread_count || 0) > 0);
    } else if (filter === 'open') {
      filtered = filtered.filter(conv => conv.status === 'open');
    } else if (filter === 'pending') {
      filtered = filtered.filter(conv => conv.status === 'pending');
    } else if (filter === 'starred') {
      filtered = filtered.filter(conv => conv.is_starred);
    } else if (filter === 'archived') {
      filtered = filtered.filter(conv => conv.status === 'archived');
    }

    return filtered.sort((a, b) => {
      const dateA = new Date(a.updated_at || a.created_at || 0);
      const dateB = new Date(b.updated_at || b.created_at || 0);
      return dateB - dateA;
    });
  }, [conversations, search, filter, isAdmin]);

  const getOtherUserName = (conversation) => {
    if (isAdmin) {
      const firstName = conversation.user_first_name || '';
      const lastName = conversation.user_last_name || '';
      const name = `${firstName} ${lastName}`.trim();
      return name || 'Utilisateur';
    } else {
      const firstName = conversation.admin_first_name || '';
      const lastName = conversation.admin_last_name || '';
      const name = `${firstName} ${lastName}`.trim();
      return name || 'Conseiller Premium';
    }
  };

  const getOtherUserEmail = (conversation) => {
    if (isAdmin) {
      return conversation.user_email || conversation.email || '';
    }
    return '';
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'open': return 'bg-emerald-500';
      case 'pending': return 'bg-amber-500';
      case 'closed': return 'bg-neutral-500';
      case 'archived': return 'bg-purple-500';
      default: return 'bg-blue-500';
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'open': return 'Ouvert';
      case 'pending': return 'En attente';
      case 'closed': return 'Fermé';
      case 'archived': return 'Archivé';
      default: return 'Nouveau';
    }
  };

  const getInitials = (name) => {
    if (!name) return '?';
    const names = name.split(' ');
    if (names.length >= 2) {
      return (names[0].charAt(0) + names[1].charAt(0)).toUpperCase();
    }
    return name.charAt(0).toUpperCase();
  };

  const formatTime = (dateString) => {
    if (!dateString) return 'À l\'instant';

    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return 'À l\'instant';
    if (diffMins < 60) return `Il y a ${diffMins} min`;
    if (diffHours < 24) return `Il y a ${diffHours} h`;
    if (diffDays === 1) return 'Hier';
    if (diffDays < 7) return `Il y a ${diffDays} j`;

    return date.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
  };

  const getLastMessagePreview = (conversation) => {
    if (!conversation.last_message) return 'Commencez la conversation...';

    const message = conversation.last_message;
    if (message.length > 60) {
      return message.substring(0, 57) + '...';
    }
    return message;
  };

  const getConversationBadges = (conversation) => {
    const badges = [];

    if (conversation.is_starred) {
      badges.push({ icon: Star, color: 'text-yellow-500', bg: 'bg-yellow-500/10' });
    }

    if (conversation.is_pinned) {
      badges.push({ icon: Pin, color: 'text-blue-500', bg: 'bg-blue-500/10' });
    }

    if (isAdmin && conversation.user_is_premium) {
      badges.push({ icon: Crown, color: 'text-purple-500', bg: 'bg-purple-500/10' });
    }

    if (conversation.is_urgent) {
      badges.push({ icon: Shield, color: 'text-red-500', bg: 'bg-red-500/10' });
    }

    return badges;
  };

  return (
    <div className="relative h-full flex flex-col bg-gradient-to-br from-white via-white to-white/95 dark:from-neutral-900 dark:via-neutral-900 dark:to-neutral-900/95 rounded-2xl shadow-2xl shadow-primary-500/5 border border-white/20 dark:border-neutral-800/50 overflow-hidden backdrop-blur-sm">

      {/* Header avec effet glassmorphism */}
      <div className="flex-shrink-0 p-5 bg-gradient-to-r from-white/80 to-white/60 dark:from-neutral-900/80 dark:to-neutral-800/60 border-b border-white/20 dark:border-neutral-800/50 backdrop-blur-md">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <div className="relative">
              <div className="h-10 w-10 rounded-xl bg-gradient-to-br from-primary-500 via-primary-600 to-secondary-600 flex items-center justify-center shadow-lg shadow-primary-500/20">
                <MessageSquare className="w-5 h-5 text-white" />
              </div>
              <div className="absolute -top-1 -right-1 h-4 w-4 rounded-full bg-emerald-500 border-2 border-white dark:border-neutral-900"></div>
            </div>
            <div>
              <h2 className="text-xl font-bold text-neutral-900 dark:text-white">
                {isAdmin ? 'Support Client' : 'Mes Messages'}
              </h2>
              <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-0.5">
                {conversations.length} conversation{conversations.length !== 1 ? 's' : ''}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {isAdmin && (
              <div className="px-2 py-1 bg-emerald-500/10 border border-emerald-500/20 rounded-lg">
                <span className="text-xs font-medium text-emerald-600 dark:text-emerald-400">Admin</span>
              </div>
            )}
            <button className="p-2 hover:bg-white/20 dark:hover:bg-white/10 rounded-lg transition-all">
              <Sparkles className="w-4 h-4 text-primary-500" />
            </button>
          </div>
        </div>

        {/* Barre de recherche stylée */}
        <div className="relative group">
          <div className="absolute inset-0 bg-gradient-to-r from-primary-500/10 to-secondary-500/10 rounded-xl blur opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-400 group-hover:text-primary-500 transition-colors" size={18} />
            <input
              type="text"
              placeholder={isAdmin ? "Rechercher un client..." : "Rechercher une conversation..."}
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-10 pr-4 py-3 bg-white/50 dark:bg-neutral-800/50 border border-white/30 dark:border-neutral-700/50 rounded-xl text-sm text-neutral-900 dark:text-white placeholder-neutral-400 dark:placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-transparent backdrop-blur-sm transition-all duration-200"
            />
          </div>
        </div>

        {/* Filtres avec style moderne */}
        <div className="flex items-center justify-between mt-4">
          <div className="flex items-center gap-1.5">
            <Filter className="w-4 h-4 text-neutral-400" />
            <span className="text-xs font-medium text-neutral-500">Filtrer:</span>
          </div>
          <div className="flex flex-wrap gap-1.5">
            {[
              { id: 'all', label: 'Tous', icon: null },
              { id: 'unread', label: 'Non lus', icon: null },
              { id: 'open', label: 'Ouverts', icon: null },
              { id: 'pending', label: 'En attente', icon: null },
              ...(isAdmin ? [] : [
                { id: 'starred', label: 'Favoris', icon: Star },
                { id: 'archived', label: 'Archivés', icon: Archive }
              ])
            ].map((item) => (
              <button
                key={item.id}
                onClick={() => setFilter(item.id)}
                className={`px-3 py-1.5 text-xs font-medium rounded-lg transition-all duration-200 flex items-center gap-1.5 ${
                  filter === item.id
                    ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg shadow-primary-500/25'
                    : 'bg-white/40 dark:bg-neutral-800/40 text-neutral-700 dark:text-neutral-300 hover:bg-white/60 dark:hover:bg-neutral-700/60 border border-white/30 dark:border-neutral-700/30'
                }`}
              >
                {item.icon && <item.icon className="w-3 h-3" />}
                {item.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Liste des conversations */}
      <div className="flex-1 overflow-y-auto p-2">
        {loading && conversations.length === 0 ? (
          <div className="p-8 text-center">
            <div className="relative">
              <div className="animate-spin rounded-full h-10 w-10 border-3 border-primary-500/30 border-t-primary-500 mx-auto"></div>
              <Sparkles className="absolute inset-0 m-auto w-4 h-4 text-primary-500 animate-pulse" />
            </div>
            <p className="text-neutral-500 mt-3">Chargement des conversations...</p>
          </div>
        ) : filteredConversations.length === 0 ? (
          <div className="p-8 text-center">
            <div className="h-20 w-20 rounded-2xl bg-gradient-to-br from-primary-500/10 to-secondary-500/10 flex items-center justify-center mx-auto mb-4">
              <User className="h-10 w-10 text-primary-500/50" />
            </div>
            <h3 className="text-lg font-semibold text-neutral-900 dark:text-white mb-2">
              {search ? 'Aucun résultat' : 'Aucune conversation'}
            </h3>
            <p className="text-sm text-neutral-500 dark:text-neutral-400 max-w-xs mx-auto">
              {search 
                ? 'Essayez avec d\'autres termes de recherche'
                : isAdmin 
                  ? 'Attendez qu\'un utilisateur crée une conversation'
                  : 'Créez votre première conversation avec notre équipe'
              }
            </p>
          </div>
        ) : (
          <div className="space-y-1.5">
            {filteredConversations.map(conversation => {
              const isSelected = currentConversation?.id === conversation.id;
              const otherUserName = getOtherUserName(conversation);
              const otherUserEmail = getOtherUserEmail(conversation);
              const unreadCount = conversation.unread_count || 0;
              const badges = getConversationBadges(conversation);
              const isHovered = hoveredConversation === conversation.id;

              return (
                <div
                  key={conversation.id}
                  onMouseEnter={() => setHoveredConversation(conversation.id)}
                  onMouseLeave={() => setHoveredConversation(null)}
                  onClick={() => {
                    console.log('🖱️ Conversation cliquée:', conversation);
                    onSelectConversation(conversation);
                  }}
                  className={`relative p-3 rounded-xl cursor-pointer transition-all duration-300 transform ${
                    isSelected
                      ? 'bg-gradient-to-r from-primary-500/10 to-secondary-500/10 border border-primary-500/20 shadow-lg shadow-primary-500/10 scale-[1.02]'
                      : 'hover:bg-white/60 dark:hover:bg-neutral-800/60 border border-transparent hover:border-white/20 dark:hover:border-neutral-700/50 hover:shadow-lg'
                  } ${isHovered && !isSelected ? 'translate-x-1' : ''}`}
                >
                  {/* Effet de fond au survol */}
                  {isHovered && !isSelected && (
                    <div className="absolute inset-0 bg-gradient-to-r from-primary-500/5 to-secondary-500/5 rounded-xl blur opacity-50"></div>
                  )}

                  <div className="relative flex items-start justify-between gap-3">
                    {/* Avatar avec badge de statut */}
                    <div className="relative flex-shrink-0">
                      <div className="relative">
                        <div className={`h-10 w-10 rounded-xl bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center text-white font-bold shadow-lg`}>
                          {getInitials(otherUserName)}
                        </div>

                        {/* Badge de statut */}
                        <div className={`absolute -bottom-1 -right-1 h-4 w-4 rounded-full ${getStatusColor(conversation.status)} border-2 border-white dark:border-neutral-900`}></div>

                        {/* Badge VIP si premium */}
                        {isAdmin && conversation.user_is_premium && (
                          <div className="absolute -top-1 -left-1">
                            <Crown className="w-4 h-4 text-yellow-500 fill-yellow-500" />
                          </div>
                        )}
                      </div>
                    </div>

                    {/* Contenu principal */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between gap-2">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1">
                            <h3 className="text-sm font-semibold text-neutral-900 dark:text-white truncate">
                              {otherUserName}
                            </h3>

                            {/* Badges */}
                            <div className="flex items-center gap-1">
                              {badges.map((badge, index) => (
                                <div key={index} className={`p-0.5 rounded ${badge.bg}`}>
                                  <badge.icon className={`w-3 h-3 ${badge.color}`} />
                                </div>
                              ))}

                              {conversation.status !== 'open' && (
                                <span className={`px-1.5 py-0.5 text-[10px] font-bold ${getStatusColor(conversation.status)}/20 text-${getStatusColor(conversation.status).split('-')[1]}-600 dark:text-${getStatusColor(conversation.status).split('-')[1]}-400 rounded`}>
                                  {getStatusText(conversation.status)}
                                </span>
                              )}

                              {unreadCount > 0 && (
                                <span className="flex-shrink-0 px-1.5 py-0.5 text-[10px] font-bold bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded">
                                  {unreadCount}
                                </span>
                              )}
                            </div>
                          </div>

                          {/* Email et titre */}
                          <div className="space-y-0.5">
                            {isAdmin && otherUserEmail && (
                              <div className="flex items-center gap-1">
                                <Mail className="w-3 h-3 text-neutral-400" />
                                <p className="text-xs text-neutral-500 truncate">
                                  {otherUserEmail}
                                </p>
                              </div>
                            )}

                            {conversation.title && (
                              <p className="text-xs text-neutral-500 truncate">
                                {conversation.title}
                              </p>
                            )}
                          </div>

                          {/* Dernier message */}
                          <p className="text-sm text-neutral-600 dark:text-neutral-300 truncate mt-2">
                            {getLastMessagePreview(conversation)}
                          </p>
                        </div>

                        {/* Côté droit - Heure et actions */}
                        <div className="flex flex-col items-end gap-2">
                          <div className="flex items-center gap-1">
                            <Clock className="w-3 h-3 text-neutral-400" />
                            <span className="text-xs text-neutral-500 whitespace-nowrap">
                              {formatTime(conversation.last_message_time || conversation.updated_at)}
                            </span>
                          </div>

                          {/* Menu d'actions (apparaît au survol) */}
                          {isHovered && (
                            <div className="relative">
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setShowMenu(showMenu === conversation.id ? null : conversation.id);
                                }}
                                className="p-1 hover:bg-white/20 dark:hover:bg-white/10 rounded"
                              >
                                <MoreVertical className="w-4 h-4 text-neutral-400" />
                              </button>

                              {showMenu === conversation.id && (
                                <div className="absolute right-0 top-full mt-1 w-32 bg-white dark:bg-neutral-800 rounded-lg shadow-xl border border-white/20 dark:border-neutral-700/50 z-10">
                                  <button className="w-full px-3 py-2 text-xs text-left hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-t-lg flex items-center gap-2">
                                    <Star className="w-3 h-3" />
                                    Favoris
                                  </button>
                                  <button className="w-full px-3 py-2 text-xs text-left hover:bg-neutral-100 dark:hover:bg-neutral-700 flex items-center gap-2">
                                    <Pin className="w-3 h-3" />
                                    Épingler
                                  </button>
                                  <button className="w-full px-3 py-2 text-xs text-left hover:bg-neutral-100 dark:hover:bg-neutral-700 flex items-center gap-2">
                                    <Archive className="w-3 h-3" />
                                    Archiver
                                  </button>
                                  <button className="w-full px-3 py-2 text-xs text-left hover:bg-red-50 dark:hover:bg-red-900/20 text-red-500 rounded-b-lg flex items-center gap-2">
                                    <Trash2 className="w-3 h-3" />
                                    Supprimer
                                  </button>
                                </div>
                              )}
                            </div>
                          )}

                          {/* Indicateur de lecture */}
                          {unreadCount === 0 && !isHovered && (
                            <CheckCheck className="w-4 h-4 text-emerald-500" />
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Footer avec statistiques */}
      <div className="flex-shrink-0 p-3 border-t border-white/20 dark:border-neutral-800/50 bg-white/30 dark:bg-neutral-900/30 backdrop-blur-sm">
        <div className="flex items-center justify-between text-xs text-neutral-500">
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-1">
              <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
              <span>{conversations.filter(c => c.status === 'open').length} ouvert</span>
            </div>
            <div className="flex items-center gap-1">
              <div className="w-2 h-2 rounded-full bg-amber-500"></div>
              <span>{conversations.filter(c => c.status === 'pending').length} en attente</span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <div className="flex items-center gap-1">
              <MessageSquare className="w-3 h-3" />
              <span>{conversations.length} total</span>
            </div>
            {conversations.some(c => c.unread_count > 0) && (
              <div className="flex items-center gap-1">
                <div className="w-2 h-2 rounded-full bg-primary-500 animate-pulse"></div>
                <span className="text-primary-600 dark:text-primary-400">
                  {conversations.reduce((sum, c) => sum + (c.unread_count || 0), 0)} non lus
                </span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default MessagesList;
